38	// 此时亏损 0 未触线、金额合计恰满，两项限额都允许保留该部分成交买单。
39	func riskAmountGapSetup(t *testing.T) (e *Engine, bPartial int64) {
40		t.Helper()
41		e, _ = NewEngine(1000)
42		mustSetMax(t, e, "A", 100)
43		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
44		b0 := mustBuy(t, e, "A", 10, 10)
45		if _, err := e.Fill(Trade{TradeID: 1, OrderID: b0, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
46			t.Fatal(err)
47		}
48		if err := e.StartTradingDay(1, 50); err != nil {
49			t.Fatal(err)
50		}
51		bPartial = mustBuy(t, e, "A", 20, 8)
52		if _, err := e.Fill(Trade{TradeID: 2, OrderID: bPartial, Symbol: "A", Side: Buy, Price: 8, Qty: 2}); err != nil {
53			t.Fatal(err)
54		}
55		if _, err := e.SetPositionAmountLimit(300); err != nil {
56			t.Fatal(err)
57		}
58	
59		if e.Cash() != 884 || e.ReservedCash() != 144 || e.Position("A") != 12 {
60			t.Fatalf("前置状态错误: cash=%d reserved=%d pos=%d",
61				e.Cash(), e.ReservedCash(), e.Position("A"))
62		}
63		st := e.RiskStatus()
64		if !st.Open || st.Restricted || st.Equity != 1004 || st.Loss != 0 {
65			t.Fatalf("提交前必须未触线: %+v", st)
66		}
67		am := e.PositionAmountStatus()
68		if !am.Enabled || am.Limit != 300 || am.Holding != 120 || am.BuyReserved != 180 || am.Total != 300 {
69			t.Fatalf("提交前金额状态必须恰好允许保留该买单: %+v", am)
70		}
71		return e, bPartial
72	}
73	
74	// TestRiskAmountGapFillLossCanceledBuyExcludedFromLaterQuote 覆盖成功路径：
75	// seq3@5 使亏损 56 达到上限 50（链中触线，撤销买单剩余 18 股）；seq4 大幅
76	// 回升，12×p4 与现金加持仓净值都可表示，但 18×p4 必然溢出。若实现错误地把
77	// 已撤剩余量计入 seq4 的金额计算，整批会被误判溢出而回滚；正确实现必须成功。
78	func TestRiskAmountGapFillLossCanceledBuyExcludedFromLaterQuote(t *testing.T) {
79		e, bPartial := riskAmountGapSetup(t)
80	
81		// p4 = MaxInt64/18 + 1：已撤的 18 股若被计入则 18×p4 溢出；
82		// 真实持仓 12×p4 与净值 884+12×p4 都可表示。
83		p4 := int64(math.MaxInt64/18 + 1)
84		wantHolding := 12 * p4
85		wantEquity := 884 + wantHolding
