150		}
151	
152		// 最新报价推进到末条，缺口消失。
153		q, ok := e.CurrentQuote("A")
154		if !ok || q.Seq != 4 || q.Price != p4 {
155			t.Fatalf("最新报价应推进到末条 seq4@p4: %+v ok=%v", q, ok)
156		}
157		if e.HasGap("A") {
